import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";

/**
 * Rate limit error detail following RFC 7807 (Problem Details for HTTP APIs). Returned by the API
 * Gateway when the request threshold is violated.
 */
export type ErrorDetail429 = {
  /** A URI reference that identifies the problem type. */
  type?: string;
  /** A short, human-readable summary of the problem type. */
  title?: string;
  /** The HTTP status code generated by the origin server for this occurrence of the problem. */
  status?: number;
  /** A human-readable explanation specific to this occurrence of the problem. */
  detail?: string;
  /** A URI reference that identifies the specific occurrence of the problem. */
  instance?: string;
};

export const errorDetail429Schema: Schema<ErrorDetail429> = s.object<ErrorDetail429>({
  type: s.optional(s.string()),
  title: s.optional(s.string()),
  status: s.optional(s.int()),
  detail: s.optional(s.string()),
  instance: s.optional(s.string()),
});
